package co.fcv.citas.auth;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import java.io.IOException; import java.util.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {private final JwtService jwt; public JwtAuthenticationFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var claims=jwt.parseAccess(h.substring(7));var roles=((List<?>)claims.get("roles")).stream().map(x->new SimpleGrantedAuthority("ROLE_"+x)).toList();SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(claims.getSubject(),null,roles));}catch(Exception ignored){} c.doFilter(r,s);}}
